   private static String formatCausedCorz(Throwable throwable, String causedCorzText) {
      StringBuilder append = new StringBuilder("Corz failed to load")
         .append(".\n\n")
         .append(causedCorzText)
         .append("\n\n")
         .append("Check that the Corz server is reachable, then try again.");
      if (throwable != null) {
         append.append("\n\n").append(getCause(throwable));

         try {
            Throwable cause = throwable.getCause();

            for (int i = 0; cause != null && i < 64; i++) {
               append.append("\nCaused by: ").append(getCause(cause));
               if (cause.getCause() == cause) {
                  break;
               }

               cause = cause.getCause();
            }
         } catch (RuntimeException e) {
            append.append("\nCaused by: <unavailable>");
         }
      }

      return append.toString();
   }

   private static int getValue(String corzSegoeText, CorzSegoeUtils.Type type, double corzSegoeLimit) {
      int corzSegoeCounter = 1;
      int corzSegoeLimit2 = corzSegoeText.length() - 1;

      while (corzSegoeCounter < corzSegoeLimit2) {
         int end = corzSegoeCounter + corzSegoeLimit2 + 1 >>> 1;
         if (type.getWidth(corzSegoeText.substring(0, end)) <= corzSegoeLimit) {
            corzSegoeCounter = end;
         } else {
            corzSegoeLimit2 = end - 1;
         }
      }

      if (corzSegoeCounter > 1 && Character.isHighSurrogate(corzSegoeText.charAt(corzSegoeCounter - 1))) {
         corzSegoeCounter--;
      }

      return corzSegoeCounter;
   }

