   private static final class Eased {
      double targetValue;
      long easedValue;
      final double easedAmount;
      double amountTime;

      boolean canAmountTime(double amount, long nanoTime) {
         if (amount == this.targetValue) {
            return false;
         } else {
            this.amountTime = this.getAmountTime(nanoTime);
            this.targetValue = amount;
            this.easedValue = nanoTime;
            return true;
         }
      }

      Eased(double amount) {
         this.easedAmount = amount;
      }

      double getAmountTime(long easedValue) {
         return this.amountTime + (this.targetValue - this.amountTime) * CorzSegoeUtils.getAmount((easedValue - this.easedValue) / 1.0E9 / this.easedAmount);
      }
   }

