      private void updateBootstrapDeadline() {
         try {
            while (this.threadActive) {
               if (System.nanoTime() < this.bootstrapStatusDeadline) {
                  this.repaint();
                  Thread.sleep(16L);
               } else {
                  synchronized (this.bootstrapDeadlineObject) {
                     if (this.threadActive && System.nanoTime() >= this.bootstrapStatusDeadline) {
                        this.bootstrapDeadlineObject.wait();
                     }
                  }
               }
            }
         } catch (InterruptedException e) {
         }
      }

      private void handleBootstrapDeadline(long bootstrapStatusDeadline) {
         if (bootstrapStatusDeadline > this.bootstrapStatusDeadline) {
            this.bootstrapStatusDeadline = bootstrapStatusDeadline;
         }

         synchronized (this.bootstrapDeadlineObject) {
            this.bootstrapDeadlineObject.notifyAll();
         }
      }

